import unittest
import app

class ContractTests(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(app.process([1, 2]), {'status': 'complete', 'processed': [1, 2]})

    def test_cancelled(self):
        self.assertEqual(app.process([1, 2], True), {'status': 'cancelled', 'processed': []})

    def test_cancel_before_enumeration(self):
        def forbidden():
            raise AssertionError('cancelled work was enumerated')
            yield 1
        self.assertEqual(app.process(forbidden(), True), {'status': 'cancelled', 'processed': []})
